/**
 * One description per provider: catalogue card, tool capability and gateway registration read this.
 *
 * Generated from the pre-V4 catalogue and capability table during the manifest migration, then kept as
 * the source. `tools`, `toolChoice` and `web` are the capability row; every other field is the card.
 * `src/data/providers.ts` and `Kernel/Tools/src/caps.ts` project from this file, so a provider cannot
 * have two descriptions again.
 */
export type ProviderManifest = {
  id: string;
  /** Present in the dashboard catalogue. A capability-only id is not a card. */
  catalog: boolean;
  name: string;
  description: string;
  category: string;
  group: string;
  status: string;
  auth: string;
  models: string;
  latency: string;
  requests: string;
  lastUsed: string;
  health: number;
  color: string;
  initial: string;
  logo?: string;
  endpoint?: string;
  modelList: readonly string[];
  catalogId?: string;
  connectionProviderId?: string;
  freeTier?: string;
  authModes?: readonly string[];
  riskNotice?: string;
  riskSeverity?: string;
  healthVerified?: string;
  unavailableReason?: string;
  apiKeysUrl?: string;
  accountCount?: number;
  baseUrl?: string;
  modelsUrl?: string;
  usageUrl?: string;
  registryAuth?: 'oauth' | 'api-key' | 'web' | 'none';
  formats?: readonly string[];
  tools: boolean;
  toolChoice: readonly ('auto' | 'none' | 'required')[];
  web: boolean;
};

